// Each input item corresponds to one Space, with:
//   item.json (from first input)  -> { folders: [...] }  (from Get Folders for Space)
//   item.json (from second input) -> { id, name, lists: [...] } (space + folderless lists)
// merge node with combineByPosition outputs items containing both branches' fields merged

const results = [];

for (const item of items) {
  const data = item.json;

  const spaceId = data.id;
  const spaceName = data.name;

  // Folderless lists (from the space's `list` field, if present)
  const folderlessLists = data.lists || [];
  for (const list of folderlessLists) {
    results.push({
      space_id: spaceId,
      space_name: spaceName,
      folder_id: null,
      folder_name: null,
      list_id: list.id,
      list_name: list.name
    });
  }

  // Folders -> fetch lists within each folder
  const folders = data.folders || [];
  for (const folder of folders) {
    // folder.lists is often included directly in the folder object from the ClickUp API
    const folderLists = folder.lists || [];
    if (folderLists.length > 0) {
      for (const list of folderLists) {
        results.push({
          space_id: spaceId,
          space_name: spaceName,
          folder_id: folder.id,
          folder_name: folder.name,
          list_id: list.id,
          list_name: list.name
        });
      }
    } else {
      // Fallback: fetch lists for this folder via API if not embedded
      const response = await this.helpers.httpRequestWithAuthentication.call(
        this,
        'clickUpApi',
        {
          method: 'GET',
          url: `https://api.clickup.com/api/v2/folder/${folder.id}/list`,
          qs: { archived: 'false' },
          json: true
        }
      );
      const lists = response.lists || [];
      for (const list of lists) {
        results.push({
          space_id: spaceId,
          space_name: spaceName,
          folder_id: folder.id,
          folder_name: folder.name,
          list_id: list.id,
          list_name: list.name
        });
      }
      // If folder has no lists at all, still record the folder so it's visible
      if (lists.length === 0) {
        results.push({
          space_id: spaceId,
          space_name: spaceName,
          folder_id: folder.id,
          folder_name: folder.name,
          list_id: null,
          list_name: null
        });
      }
    }
  }

  // If a space has neither folders nor folderless lists, still record it
  if (folders.length === 0 && folderlessLists.length === 0) {
    results.push({
      space_id: spaceId,
      space_name: spaceName,
      folder_id: null,
      folder_name: null,
      list_id: null,
      list_name: null
    });
  }
}

return results.map(r => ({ json: r }));

// Sort for readability: space, then folder, then list
const sorted = [...items.map(i => i.json)].sort((a, b) => {
  if (a.space_name !== b.space_name) return (a.space_name || '').localeCompare(b.space_name || '');
  if ((a.folder_name || '') !== (b.folder_name || '')) return (a.folder_name || '').localeCompare(b.folder_name || '');
  return (a.list_name || '').localeCompare(b.list_name || '');
});

return sorted.map(r => ({ json: r }));

// Filter ClickUp v3 chat channels down to real project channels, and join
// against the Lists/Folders table (Code - Format as Table) to attach
// human-readable names and resolve folder-level channels to their member lists.
//
// parent.type codes observed: 5 = Folder, 6 = List, 7 = Space, 12 = Workspace-level (DM/group DM/non-project)

let listsTable = [];
try {
  listsTable = $('Code - Format as Table').all().map(i => i.json);
} catch (e) {
  listsTable = [];
}

const results = [];

for (const item of items) {
  const ch = item.json;

  // Only real, current project channels
  if (ch.type !== 'CHANNEL') continue;
  if (ch.is_canonical_channel !== true) continue;
  if (!ch.parent || ![5, 6].includes(ch.parent.type)) continue;

  const parentId = ch.parent.id;

  if (ch.parent.type === 6) {
    // Channel attached to a single List
    const row = listsTable.find(r => r.list_id === parentId);
    results.push({
      channel_id: ch.id,
      channel_name: ch.name,
      attached_to: 'list',
      list_id: parentId,
      list_name: row ? row.list_name : null,
      folder_id: row ? row.folder_id : null,
      folder_name: row ? row.folder_name : null,
      latest_comment_at: ch.latest_comment_at || null
    });
  } else if (ch.parent.type === 5) {
    // Channel attached to a Folder - covers every list within that folder
    const rows = listsTable.filter(r => r.folder_id === parentId);
    if (rows.length > 0) {
      for (const row of rows) {
        results.push({
          channel_id: ch.id,
          channel_name: ch.name,
          attached_to: 'folder',
          list_id: row.list_id,
          list_name: row.list_name,
          folder_id: parentId,
          folder_name: row.folder_name,
          latest_comment_at: ch.latest_comment_at || null
        });
      }
    } else {
      // Folder with no lists found in the table - still record the channel
      results.push({
        channel_id: ch.id,
        channel_name: ch.name,
        attached_to: 'folder',
        list_id: null,
        list_name: null,
        folder_id: parentId,
        folder_name: null,
        latest_comment_at: ch.latest_comment_at || null
      });
    }
  }
}

// Sort for readability: folder, then list, then channel name
results.sort((a, b) => {
  if ((a.folder_name || '') !== (b.folder_name || '')) return (a.folder_name || '').localeCompare(b.folder_name || '');
  if ((a.list_name || '') !== (b.list_name || '')) return (a.list_name || '').localeCompare(b.list_name || '');
  return (a.channel_name || '').localeCompare(b.channel_name || '');
});

return results.map(r => ({ json: r }));
